// AiDocSelect is the builder for selecting fields of AiDoc entities.
type AiDocSelect struct {
	*AiDocQuery
	selector
}

// Aggregate adds the given aggregation functions to the selector query.
func (_s *AiDocSelect) Aggregate(fns ...AggregateFunc) *AiDocSelect {
	_s.fns = append(_s.fns, fns...)
	return _s
}

// Scan applies the selector query and scans the result into the given value.
func (_s *AiDocSelect) Scan(ctx context.Context, v any) error {
	ctx = setContextOp(ctx, _s.ctx, ent.OpQuerySelect)
	if err := _s.prepareQuery(ctx); err != nil {
		return err
	}
	return scanWithInterceptors[*AiDocQuery, *AiDocSelect](ctx, _s.AiDocQuery, _s, _s.inters, v)
}

func (_s *AiDocSelect) sqlScan(ctx context.Context, root *AiDocQuery, v any) error {
	selector := root.sqlQuery(ctx)
	aggregation := make([]string, 0, len(_s.fns))
	for _, fn := range _s.fns {
		aggregation = append(aggregation, fn(selector))
	}
	switch n := len(*_s.selector.flds); {
	case n == 0 && len(aggregation) > 0:
		selector.Select(aggregation...)
	case n != 0 && len(aggregation) > 0:
		selector.AppendSelect(aggregation...)
	}
	rows := &sql.Rows{}
	query, args := selector.Query()
	if err := _s.driver.Query(ctx, query, args, rows); err != nil {
		return err
	}
	defer rows.Close()
	return sql.ScanSlice(rows, v)
}

// Modify adds a query modifier for attaching custom logic to queries.
func (_s *AiDocSelect) Modify(modifiers ...func(s *sql.Selector)) *AiDocSelect {
	_s.modifiers = append(_s.modifiers, modifiers...)
	return _s
}
